.calendar-tooltip { position: fixed; inset: auto; margin: 0; padding: 14px 16px; inline-size: max-content; max-inline-size: min(260px, calc(100% - 16px)); border: 0; border-radius: 10px; background: #304d39; color: #f9fcf6; box-shadow: 0 8px 24px #203d2526; font-size: 12px; line-height: 1.65; z-index: 30; overflow-wrap: anywhere; }
